From 736c60713dfe7f45ac007f58ec623abaee0304a3 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 22:58:21 +0100
Subject: [PATCH] plugins/memory: only list swap sensors when the system has
 swap

On systems without swap the Swap Memory sensors were always listed in
the sensor picker even though they can only ever read zero. Now the swap
object is only added while swap is available, following swapon/swapoff.

BUG: 462707
---
 plugins/memory/backend.cpp        | 18 +++++++++++++++++-
 plugins/memory/backend.h          |  3 +++
 plugins/memory/freebsdbackend.cpp |  1 +
 plugins/memory/linuxbackend.cpp   | 13 +++++++++++++
 plugins/memory/linuxbackend.h     |  3 +++
 5 files changed, 37 insertions(+), 1 deletion(-)

diff --git a/plugins/memory/backend.cpp b/plugins/memory/backend.cpp
index ef8b880..47173a4 100644
--- a/plugins/memory/backend.cpp
+++ b/plugins/memory/backend.cpp
@@ -7,15 +7,31 @@
 #include "backend.h"

 #include <systemstats/AggregateSensor.h>
+#include <systemstats/SensorContainer.h>
 #include <systemstats/SensorObject.h>
 #include <systemstats/SensorProperty.h>

 #include <KLocalizedString>

 MemoryBackend::MemoryBackend(KSysGuard::SensorContainer *container)
+    : m_container(container)
 {
     m_physicalObject = new KSysGuard::SensorObject(QStringLiteral("physical"), i18nc("@title", "Physical Memory"), container);
-    m_swapObject = new KSysGuard::SensorObject(QStringLiteral("swap"), i18nc("@title", "Swap Memory"), container);
+    m_swapObject = new KSysGuard::SensorObject(QStringLiteral("swap"), i18nc("@title", "Swap Memory"));
+    m_swapObject->setParent(container);
+}
+
+void MemoryBackend::setSwapAvailable(bool available)
+{
+    if (available == (m_container->object(m_swapObject->id()) == m_swapObject)) {
+        return;
+    }
+
+    if (available) {
+        m_container->addObject(m_swapObject);
+    } else {
+        m_container->removeObject(m_swapObject);
+    }
 }

 void MemoryBackend::makeSensors()
diff --git a/plugins/memory/backend.h b/plugins/memory/backend.h
index 52f300b..43eb12b 100644
--- a/plugins/memory/backend.h
+++ b/plugins/memory/backend.h
@@ -22,6 +22,9 @@ public:
     virtual void update() = 0;
 protected:
     virtual void makeSensors();
+    void setSwapAvailable(bool available);
+
+    KSysGuard::SensorContainer *m_container = nullptr;

     KSysGuard::SensorProperty *m_total = nullptr;
     KSysGuard::SensorProperty *m_used = nullptr;
diff --git a/plugins/memory/freebsdbackend.cpp b/plugins/memory/freebsdbackend.cpp
index 8878b2b..bf3280b 100644
--- a/plugins/memory/freebsdbackend.cpp
+++ b/plugins/memory/freebsdbackend.cpp
@@ -35,6 +35,7 @@ FreeBsdMemoryBackend::FreeBsdMemoryBackend(KSysGuard::SensorContainer* container
     if (!m_kd) {
         qCWarning(KSYSTEMSTATS_MEMORY) << errorBuffer;
     }
+    setSwapAvailable(true);
 }

 void FreeBsdMemoryBackend::makeSensors()
diff --git a/plugins/memory/linuxbackend.cpp b/plugins/memory/linuxbackend.cpp
index 40b3486..5646af0 100644
--- a/plugins/memory/linuxbackend.cpp
+++ b/plugins/memory/linuxbackend.cpp
@@ -12,13 +12,26 @@

 #include <QFile>

+#include <sys/sysinfo.h>
+
 LinuxMemoryBackend::LinuxMemoryBackend(KSysGuard::SensorContainer *container)
     : MemoryBackend(container)
 {
+    updateSwapAvailable();
+}
+
+void LinuxMemoryBackend::updateSwapAvailable()
+{
+    struct sysinfo info;
+    if (sysinfo(&info) == 0) {
+        setSwapAvailable(info.totalswap > 0);
+    }
 }

 void LinuxMemoryBackend::update()
 {
+    updateSwapAvailable();
+
     if (!m_physicalObject->isSubscribed() && !m_swapObject->isSubscribed()) {
         return;
     }
diff --git a/plugins/memory/linuxbackend.h b/plugins/memory/linuxbackend.h
index 16a0eaa..47fd550 100644
--- a/plugins/memory/linuxbackend.h
+++ b/plugins/memory/linuxbackend.h
@@ -13,6 +13,9 @@ class LinuxMemoryBackend : public MemoryBackend {
 public:
     LinuxMemoryBackend(KSysGuard::SensorContainer *container);
     void update() override;
+
+private:
+    void updateSwapAvailable();
 };

 #endif
